// Online Parts Catalog: a bundled, searchable index of every top-level part available from the public
// LDraw mirrors (official library + LDraw Unofficial / BrickLink Studio parts). It carries IDs and titles
// only — geometry is downloaded on demand — so the Bricks Library can browse/search ~46k parts without
// shipping ~1.3 GB of .dat files. Generated by `scripts/build-parts-catalog.mjs` into `public/parts-catalog/`.

import { classifyLibraryCategory, normalizeLibrarySearchText, type LibraryCategory } from './bricksLibrary';

export type CatalogOrigin = 'official' | 'unofficial';

export const PARTS_CATALOG_FORMAT = 'brick-instruction-works-parts-catalog';
export const PARTS_CATALOG_FILES: ReadonlyArray<{ origin: CatalogOrigin; path: string }> = [
  { origin: 'official', path: 'parts-catalog/official.json' },
  { origin: 'unofficial', path: 'parts-catalog/unofficial.json' },
];

export interface CatalogEntry {
  id: string;
  name: string;
  origin: CatalogOrigin;
  /** Subpart / primitive helper (hidden unless "Show subparts & primitives" is on). */
  helper: boolean;
  alias: boolean;
  category: LibraryCategory;
  searchText: string;
}

export interface PartsCatalog {
  entries: ReadonlyMap<string, CatalogEntry>;
  counts: Record<CatalogOrigin, number>;
}

type RawEntry = [string, string] | [string, string, string];

/** Fallback display name for catalog rows with no usable title (e.g. Studio "UntitledModel" files). */
export function fallbackCatalogName(id: string): string {
  const printed = /(?:pb|ps|pat|pr)\d+/i.test(id);
  if (/^bb\d+/i.test(id)) return 'BrickLink Custom Assembly';
  if (/^bl_/i.test(id)) return printed ? 'Printed BrickLink Studio Part' : 'BrickLink Studio Custom Part';
  if (printed) return 'Printed Part';
  return `Part ${id.toUpperCase()}`;
}

/** Validates and converts one generated catalog JSON payload into entries. */
export function parseCatalogPayload(payload: unknown, origin: CatalogOrigin): CatalogEntry[] {
  const p = payload as { format?: string; parts?: unknown } | null;
  if (!p || p.format !== PARTS_CATALOG_FORMAT || !Array.isArray(p.parts)) return [];
  const out: CatalogEntry[] = [];
  for (const raw of p.parts as RawEntry[]) {
    if (!Array.isArray(raw) || typeof raw[0] !== 'string') continue;
    const id = raw[0].trim().toLowerCase();
    if (!id) continue;
    const flags = typeof raw[2] === 'string' ? raw[2] : '';
    const rawTitle = typeof raw[1] === 'string' ? raw[1].trim() : '';
    const titleKey = rawTitle.toLowerCase().replace(/\.dat$/, '');
    const titleIsJustId = titleKey === id || titleKey === id.replace(/^bl_/, '');
    const name = (rawTitle && !titleIsJustId && rawTitle) || fallbackCatalogName(id);
    const category = classifyLibraryCategory(id, name);
    out.push({
      id,
      name,
      origin,
      helper: flags.includes('h'),
      alias: flags.includes('a'),
      category,
      searchText: normalizeLibrarySearchText(`${id} ${name} ${category}`),
    });
  }
  return out;
}

/** Merges catalogs in priority order (first wins on duplicate IDs — official before unofficial). */
export function mergeCatalogEntries(lists: ReadonlyArray<readonly CatalogEntry[]>): PartsCatalog {
  const entries = new Map<string, CatalogEntry>();
  const counts: Record<CatalogOrigin, number> = { official: 0, unofficial: 0 };
  for (const list of lists) {
    for (const e of list) {
      if (entries.has(e.id)) continue;
      entries.set(e.id, e);
      counts[e.origin]++;
    }
  }
  return { entries, counts };
}

/**
 * Loads all bundled catalog files relative to `baseUrl`. Files that fail to load are skipped so a
 * partial catalog still works offline / on older deployments.
 */
export async function loadPartsCatalog(
  baseUrl = '',
  fetchImpl: typeof fetch = fetch,
): Promise<PartsCatalog> {
  const lists = await Promise.all(
    PARTS_CATALOG_FILES.map(async ({ origin, path }) => {
      try {
        const res = await fetchImpl(`${baseUrl}${path}`);
        if (!res.ok) return [];
        return parseCatalogPayload(await res.json(), origin);
      } catch {
        return [];
      }
    }),
  );
  return mergeCatalogEntries(lists);
}
